SELECT #{effectFlag} effectFlag, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN ETR_ENTRUST.STOCK_ID else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') THEN ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') AND ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.BUSINESS_MODEL businessModel, ETR_ENTRUST_ADD.SEC_ACCT_ID secAcctId, ETR_ENTRUST_ADD.SETTLE_SPREED settleSpeed, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',ETR_ENTRUST_ADD.TERM_DAYS,'F10',ETR_ENTRUST_ADD.TERM_DAYS,'F12',ETR_ENTRUST_ADD.TERM_DAYS,'F16',ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, decode(#{busiTypePosition01},EEBP.BID_PRICE,#{busiTypePosition02},ETR_ENTRUST_ADD.MATURE_YIELD,#{busiTypePosition03},ETR_ENTRUST.PRICE,'') etrPrice, 50 exeProgress, 50 dealProgress FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND ETR_ENTRUST.BUSINESS_MODEL = #{businessModel}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustDate}
AND ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
union all SELECT #{effectFlag} effectFlag, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST.FINPROD_TYPE2 finprodType2, ETR_ENTRUST.FINPROD_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId, ETR_ENTRUST_ADD.ASSET_TYPE_11 finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.CONTRACT_RESULT,'已签署完毕',ETR_ENTRUST.ENTRUST_AMT,0) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.BUSINESS_MODEL businessModel, ETR_ENTRUST_ADD.SEC_ACCT_ID secAcctId, ETR_ENTRUST_ADD.SETTLE_SPREED settleSpeed, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',ETR_ENTRUST_ADD.TERM_DAYS,'F10',ETR_ENTRUST_ADD.TERM_DAYS,'F12',ETR_ENTRUST_ADD.TERM_DAYS,'F16',ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, decode(#{busiTypePosition01},EEBP.BID_PRICE,#{busiTypePosition02},ETR_ENTRUST_ADD.MATURE_YIELD,#{busiTypePosition03},ETR_ENTRUST.PRICE,'') etrPrice, 50 exeProgress, 50 dealProgress FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.FINPROD_TYPE2 = 'F36' AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND ETR_ENTRUST.BUSINESS_MODEL = #{businessModel}
